// Release signing (CNG: android/ is regenerated by `expo prebuild --clean`, so it is wired here).
// - Release builds sign with the dedicated SKEPI keystore. Its path and alias are Gradle properties
//   (SKEPI_RELEASE_STORE_FILE, SKEPI_RELEASE_KEY_ALIAS; not secret). The passwords are read ONLY from
//   environment variables (SKEPI_RELEASE_STORE_PASSWORD, SKEPI_RELEASE_KEY_PASSWORD) that
//   tools/Signing.psm1 Use-SigningSecrets sets for one run; never from a properties file. Such a build
//   runs with --no-daemon so no daemon keeps them in memory. See docs/release-signing.md.
// - Missing settings fail the release build before any compilation starts.
// - `-PskepiDebugSign=true` (local E2E): signs with the Expo debug key and prints a loud warning. Such an
//   APK must never be distributed.
// - `-PskepiUnsigned=true` (F-Droid, CI): no signing config at all, so AGP writes an unsigned APK/AAB
//   (`*-release-unsigned.apk`). The release key is signed onto it later with apksigner, off CI.
//   Exclusive with -PskepiDebugSign.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// skepi:release-signing';

const GRADLE = `
${MARKER}
def skepiSigningProps = ['SKEPI_RELEASE_STORE_FILE', 'SKEPI_RELEASE_KEY_ALIAS']
def skepiSigningEnv = ['SKEPI_RELEASE_STORE_PASSWORD', 'SKEPI_RELEASE_KEY_PASSWORD']
def skepiProp = { String key -> (findProperty(key) ?: '').toString().trim() }
def skepiEnv = { String key -> System.getenv(key) ?: '' }
def skepiMissingKeys = skepiSigningProps.findAll { skepiProp(it).isEmpty() } + skepiSigningEnv.findAll { skepiEnv(it).isEmpty() }
// Passwords left in a gradle.properties file are never used; say so (names only, never values).
def skepiStoredPasswords = skepiSigningEnv.findAll { findProperty(it) != null }
if (!skepiStoredPasswords.isEmpty()) {
    logger.warn("SKEPI: \${skepiStoredPasswords.join(', ')} found as Gradle properties and ignored: release passwords come only from the environment. Delete them from gradle.properties (docs/release-signing.md).")
}
def skepiStoreFile = skepiMissingKeys.contains('SKEPI_RELEASE_STORE_FILE') ? null : file(skepiProp('SKEPI_RELEASE_STORE_FILE'))
def skepiDebugSign = skepiProp('skepiDebugSign').toBoolean()
def skepiUnsigned = skepiProp('skepiUnsigned').toBoolean()
def skepiReleaseKeyReady = skepiMissingKeys.isEmpty() && skepiStoreFile != null && skepiStoreFile.isFile()

android {
    signingConfigs {
        if (skepiReleaseKeyReady) {
            skepiRelease {
                storeFile skepiStoreFile
                storePassword skepiEnv('SKEPI_RELEASE_STORE_PASSWORD')
                keyAlias skepiProp('SKEPI_RELEASE_KEY_ALIAS')
                keyPassword skepiEnv('SKEPI_RELEASE_KEY_PASSWORD')
            }
        }
    }
    buildTypes {
        release {
            // Overrides the template's debug signing. Null (unsigned) is packaged only with
            // -PskepiUnsigned=true; otherwise skepiCheckReleaseSigning fails the build first.
            signingConfig skepiUnsigned ? null : (skepiDebugSign ? signingConfigs.debug : (skepiReleaseKeyReady ? signingConfigs.skepiRelease : null))
        }
    }
}

def skepiCheckReleaseSigning = tasks.register('skepiCheckReleaseSigning') {
    doLast {
        if (skepiUnsigned && skepiDebugSign) {
            throw new GradleException("-PskepiUnsigned=true and -PskepiDebugSign=true are exclusive.")
        }
        if (skepiUnsigned) {
            def bar = '!' * 78
            logger.warn("\\n\${bar}\\n!! SKEPI: UNSIGNED release build (-PskepiUnsigned=true): no signing config is used.\\n!! Sign it with apksigner and the release key before distributing (docs/release-process.md).\\n\${bar}\\n")
            return
        }
        if (skepiDebugSign) {
            def bar = '!' * 78
            logger.warn("\\n\${bar}\\n!! SKEPI: release build signed with the Expo DEBUG key (-PskepiDebugSign=true).\\n!! For local E2E only. NEVER distribute this APK.\\n\${bar}\\n")
            return
        }
        if (!skepiMissingKeys.isEmpty()) {
            throw new GradleException(
                "SKEPI release signing is not configured. Missing: \${skepiMissingKeys.join(', ')}.\\n" +
                "The keystore path and alias are Gradle properties; the passwords are environment variables only,\\n" +
                "set for one run by tools/Signing.psm1 Use-SigningSecrets (see docs/release-signing.md). Pass\\n" +
                "-PskepiUnsigned=true for an unsigned build (F-Droid, CI; sign it before distributing), or\\n" +
                "-PskepiDebugSign=true for a local, debug-signed E2E build that must never be distributed.")
        }
        if (!skepiStoreFile.isFile()) {
            throw new GradleException(
                "SKEPI release keystore not found at SKEPI_RELEASE_STORE_FILE=\${skepiStoreFile}. See docs/release-signing.md.")
        }
        logger.lifecycle("SKEPI: release build signed with key alias '\${skepiProp('SKEPI_RELEASE_KEY_ALIAS')}' from \${skepiStoreFile.name}")
    }
}
tasks.matching { it.name == 'preReleaseBuild' }.configureEach { dependsOn skepiCheckReleaseSigning }
`;

module.exports = (config) =>
  withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.contents.includes(MARKER)) return cfg;
    cfg.modResults.contents += GRADLE;
    return cfg;
  });
